(* [comment removed for export] *)
Definition pv_side (m : mem) (q E lo shi n : Z) : Prop := pside m lo shi [(q, n); (E, 24)] [(E, 24)].

Lemma pv_side_intro : forall m q E lo shi n,
  ACONST m -> stack0 m lo shi -> AXStatics m -> accessible m q n -> accessible m E 24 -> shvis m E (E + 24) ->
  aapp E 24 -> pv_side m q E lo shi n.
Proof.
  intros m q E lo shi n AC SK XS AP AE SV APE.
  pose proof (aapp_bounds E 24 APE ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
  split; [| exact XS]. split; [exact AC|]. split; [exact SK|]. split.
  - apply Forall_cons; [exact AP| apply Forall_cons; [exact AE| apply Forall_nil]].
  - apply Forall_cons; [| apply Forall_nil]. cbn [fst snd]. unfold AAPP_HI in *. split; [lia| split; [lia| split; [lia| exact SV]]].
Qed.

Lemma pv_side_elim : forall m q E lo shi n, pv_side m q E lo shi n ->
  ACONST m /\ stack0 m lo shi /\ AXStatics m /\ accessible m q n /\ accessible m E 24 /\ shvis m E (E + 24).
Proof.
  intros m q E lo shi n S. split; [exact (pside_aconst _ _ _ _ _ S)|]. split; [exact (pside_stack0 _ _ _ _ _ S)|].
  split; [exact (pside_statics _ _ _ _ _ S)|].
  split; [apply (pside_acc _ _ _ _ _ q n S); left; reflexivity|].
  split; [apply (pside_acc _ _ _ _ _ E 24 S); right; left; reflexivity|].
  apply (pside_shvis _ _ _ _ _ E 24 S). left. reflexivity.
Qed.

(* [comment removed for export] *)
Lemma pv_pwin : forall sp q I R E lo shi bs r0 E0, pv_pure sp q I R E lo shi bs r0 E0 -> Forall pwin (pv_W lo sp I R E).
Proof.
  intros sp q I R E lo shi bs r0 E0 (EOK & R0 & LO & CEIL & APP & QHI & ILO & IHI & IAL & RLO & RHI & RAL & APE & EAL & DIR & DQE & SPAL & SHI).
  unfold pv_W, PV_STACK, AASSIGN_STACK, AINTRIN_STACK in *.
  repeat apply Forall_cons; [| | | | | apply Forall_nil].
  - apply pwin_stack. exact CEIL.
  - apply pwin_stack. clear - CEIL LO ILO. lia.
  - apply pwin_stack. clear - CEIL LO RLO. lia.
  - eapply pwin_aapp; [exact APE| clear; lia| clear; lia].
  - exact pwin_httpcat.
Qed.

(* [comment removed for export] *)
Lemma pv_side_now : forall m m1 sp q I R E lo shi bs r0 E0,
  pv_side m q E lo shi (Z.of_nat (length bs)) -> munch (pv_W lo sp I R E) m m1 -> wmono asegs m m1 ->
  pv_pure sp q I R E lo shi bs r0 E0 ->
  ACONST m1 /\ stack0 m1 lo shi /\ AXStatics m1 /\ accessible m1 q (Z.of_nat (length bs)) /\ accessible m1 E 24 /\ shvis m1 E (E + 24).
Proof.
  intros m m1 sp q I R E lo shi bs r0 E0 S MU WM PURE. apply pv_side_elim.
  eapply pside_transport; [exact S| exact MU| exact WM| eapply pv_pwin; exact PURE].
Qed.

(* [comment removed for export] *)
Lemma pv_cat_now : forall m m1 (sp : word) I R lo g,
  AHttpCat m g -> munch [(lo, bv_unsigned sp); (I, I + 8); (R, R + 4)]%Z m m1 -> wmono asegs m m1 ->
  aceil <= lo -> bv_unsigned sp <= I -> bv_unsigned sp <= R -> lo <= bv_unsigned sp -> AHttpCat m1 g.
Proof.
  intros m m1 sp I R lo g HC MU WM CEIL ILO RLO LO. pose proof aceil_facts as (AF1 & _).
  eapply AHttpCat_transport; [exact HC| exact MU| exact WM| |];
    cbn [disjoint_from fst snd]; unfold AG_HTTP_CAT, AG_HTTP_CAT_GUARD; repeat split; lia.
Qed.

(* [comment removed for export] *)
Definition pv_ctx (m m1 : mem) (sp s0v s1v s2v rav : word) (q I R E lo shi : Z) (bs : list byte) (itv resv : Z) (E0 : ecv) (g : bool)
    (j8 junk : list byte) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -64) [CB 8 j8]
  /\ rw_cells asegs m1 (bv_unsigned sp + -56) [CB 24 junk]
  /\ rw_cells asegs m1 (bv_unsigned sp + -32) [C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells asegs m1 I [C8 (wz itv)]
  /\ rw_cells asegs m1 R [C4 (wz resv)]
  /\ rw_cells asegs m1 E (ErrCodeCells E0)
  /\ stk asegs m1 lo (bv_unsigned sp + -64)
  /\ bytes_at asegs m1 q bs
  /\ munch (pv_W lo sp I R E) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ munch [(lo, bv_unsigned sp); (I, I + 8); (R, R + 4)]%Z m m1
  /\ AHttpCat m g /\ pv_side m q E lo shi (Z.of_nat (length bs)).

(* [comment removed for export] *)
Definition pv_tctx (m m1 : mem) (sp s0v s1v s2v rav : word) (q I R E lo shi : Z) (bs : list byte) (itv resv : Z) (E0 : ecv)
    (j8 : list byte) (e : Z) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -64) [CB 8 j8]
  /\ rw_cells asegs m1 (bv_unsigned sp + -56) [C8 (wz e); C8 (wz AG_HTTP_CAT); C8 (wz 3)]
  /\ rw_cells asegs m1 (bv_unsigned sp + -32) [C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells asegs m1 I [C8 (wz itv)]
  /\ rw_cells asegs m1 R [C4 (wz resv)]
  /\ rw_cells asegs m1 E [CB 16 (le8 (wz e) ++ le8 (wz AG_HTTP_CAT)); C8 (wz (ec_flags E0))]
  /\ stk asegs m1 lo (bv_unsigned sp + -64)
  /\ bytes_at asegs m1 q bs
  /\ munch (pv_W lo sp I R E) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ AHttpCat m1 true /\ pv_side m q E lo shi (Z.of_nat (length bs)).

