    let MC := fresh "MC" in
    pose proof MEMCPY as MC; unfold asan_memcpy_stmt, amemcpy_stmt_at, amemcpy_post, AASAN_MEMCPY, AINTRIN_STACK in MC;
    callZc (MC _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ m2 (le8 (Z_to_bv 64 e) ++ le8 (Z_to_bv 64 6667152)) junk16 lo)
           (clear DST ST2 SRC MC);
    [ rewrite ?unsigned_lit by lia; exact SRC
    | rewrite ?unsigned_lit by lia; rewrite length_app, !length_le8; reflexivity
    | rewrite ?unsigned_lit by lia; exact DST
    | rewrite ?unsigned_lit by lia; lia
    | rewrite ?unsigned_lit by lia; eapply stack0_accessible; [exact SK2| lia| lia| lia]
    | rewrite ?unsigned_lit by lia; eapply accessible_sub; [exact AE2| lia| lia| lia]
    | rewrite ?unsigned_lit by lia; eapply stack0_shvis; [exact SK2| lia| lia| lia]
    | rewrite ?unsigned_lit by lia; eapply shvis_sub; [exact SV2| lia| lia| lia| lia| lia]
    | rewrite ?unsigned_lit by lia; exact ST2
    | lia
    | rewrite ?unsigned_lit by lia; lia
    | assumption
    | exact AC2
    | rewrite ?unsigned_lit by lia; lia
    | rewrite ?unsigned_lit by lia; eapply stack0_in_app_mem; [exact SK2| lia| lia]
    | rewrite ?unsigned_lit by lia; eapply aapp_in_app_mem; [exact APE| lia| lia]
    | rewrite ?unsigned_lit by lia; eapply aconst_ok_aapp; [exact APE| lia| lia]
    | rewrite ?unsigned_lit by lia; left; lia
    | rewrite ?unsigned_lit by lia; right; lia
    | ];
    clear SK2 AC2 AE2 SV2;
    lazymatch goal with
    | DST3 : rw_cells _ ?m3 E [CB _ _], MU'' : munch _ m ?m3, WM'' : wmono _ m ?m3 |- _ =>
      let AE3 := fresh "AE3" in let RD := fresh "RD" in let HC3 := fresh "HC3" in
      destruct (pv_side_now m m3 sp q I R E lo shi bs r0 E0 SIDE
                  ltac:(unfold pv_W, AG_HTTP_CAT; exact MU'') WM'' PURE) as (_ & _ & _ & _ & AE3 & _);
      assert (HC3 : AHttpCat m3 true)
        by (eapply AHttpCat_transport; [exact HC2| exact MU3| exact WM3| |];
            cbn [disjoint_from fst snd]; unfold AG_HTTP_CAT, AG_HTTP_CAT_GUARD; clear - AF1 CEIL LO EB1; repeat split; lia);
      clear HC2 MU3 WM3;
      (* [comment removed for export] *)
      step;
      pose proof (accessible_read0_sr m3 E 24 (E + 16) AE3 ltac:(lia) ltac:(clear - EAL; unhideL; Z.div_mod_to_equations; lia) ltac:(lia)) as RD;
      shchk_fast RD; clear AE3;
      join_frameA TMPa TMPb (bv_unsigned sp + -56); join_frameA DST3 ECb E;
      eapply (pv_tail _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ m m3 q I R E lo shi bs itv resv r0 E0 g j8 e loc r);
      [ unfold pv_tctx, pv_W, AG_HTTP_CAT, wz; repeat (split; [fast_eassumption|]); fast_eassumption
      | exact PURE | clear; lia | clear; vm_compute; intro; discriminate | clear; vm_compute; reflexivity
      | exact ADV | exact RESV | exact ERR | exact RV ]
    end
  end.
